import type { FeatureRuleEffect } from '../../src/domain/rules/featureEffects';

type StripPresentation<T> = T extends FeatureRuleEffect ? Omit<T, 'id' | 'summary' | 'evidence'> : never;
export type SemanticFeatureEffect = StripPresentation<FeatureRuleEffect>;

export type IgnoredRuleReason =
  | 'narrative-capability'
  | 'manual-action-resolution'
  | 'conditional-self-effect'
  | 'target-facing-effect'
  | 'qualitative-passive'
  | 'feature-resource-unmodeled'
  | 'structural-choice-unmodeled'
  | 'advancement-rule-unmodeled'
  | 'handled-by-dedicated-system'
  | 'baseline-rule-modifier-unmodeled';

export interface IgnoredRuleFragment {
  reason: IgnoredRuleReason;
  quote: string;
  because: string;
  handler?: string;
}

export interface FeatureEffectAuditEntry {
  effects: readonly SemanticFeatureEffect[];
  ignored: readonly IgnoredRuleFragment[];
}

function ignored(reason: IgnoredRuleReason, quote: string, because: string, handler?: string): IgnoredRuleFragment {
  return { reason, quote, because, ...(handler ? { handler } : {}) };
}

