export type AuditedFeatureKey = typeof FEATURE_EFFECT_AUDIT_KEYS[number];

const fx = {
  stat(target: Extract<SemanticFeatureEffect, { kind: 'statDelta' }>['target'], amount: number, amountSource?: 'proficiency'): SemanticFeatureEffect {
    return { kind: 'statDelta', target, amount, ...(amountSource ? { amountSource } : {}), automatic: true };
  },
  domainCard(count: number): SemanticFeatureEffect {
    return { kind: 'domainCardGrant', count, automatic: true };
  },
  restChoices(rest: 'any' | 'short' | 'long', count: number): SemanticFeatureEffect {
    return { kind: 'restChoiceCount', rest, count, automatic: true };
  },
  restSwap(max: number): SemanticFeatureEffect {
    return { kind: 'restMoveSwap', from: 'short', to: 'long', max, automatic: true };
  },
  restReroll(rest: 'short' | 'long', max: number, scope: 'self' | 'selfOrAlly'): SemanticFeatureEffect {
    return { kind: 'restReroll', rest, max, scope, automatic: false };
  },
  restMove(rest: 'any' | 'short' | 'long', scope: 'self' | 'party', label: string): SemanticFeatureEffect {
    return { kind: 'restMoveGrant', rest, scope, label, automatic: false };
  },
  usage(reset: 'rest' | 'longRest' | 'session' | 'scene', max: number, scope: 'feature' | 'targetFeature' | 'perOption' = 'feature', targetLabel?: string, options?: string[]): SemanticFeatureEffect {
    return { kind: 'usageLimit', reset, max, scope, ...(targetLabel ? { targetLabel } : {}), ...(options ? { options } : {}), automatic: false };
  },
  allowance(reset: 'rest' | 'longRest' | 'session' | 'scene', count: number, targetLabel: string): SemanticFeatureEffect {
    return { kind: 'usageAllowance', reset, count, targetLabel, automatic: false };
  },
  inventory(name: string, count = 1): SemanticFeatureEffect {
    return { kind: 'inventoryGrant', name, count, automatic: true };
  },
  creation(choice: 'experienceBonus' | 'customField' | 'stance' | 'element', values: { count?: number; bonus?: number; perRankCount?: number; perRankBonus?: number } = {}): SemanticFeatureEffect {
    return { kind: 'creationChoice', choice, ...values, automatic: false };
  },
  resource(resource: string, value: number): SemanticFeatureEffect {
    return { kind: 'resourceInit', resource, value, automatic: false };
  },
  advancement(count: number): SemanticFeatureEffect {
    return { kind: 'advancementGrant', target: 'companion', count, automatic: false };
  },
  companion(): SemanticFeatureEffect {
    return { kind: 'companionGrant', automatic: false };
  }
};

