export function buildFeatureEffectAudit(): Record<AuditedFeatureKey, FeatureEffectAuditEntry> {
  return Object.fromEntries(FEATURE_EFFECT_AUDIT_KEYS.map((key) => {
    const effects = EXPECTED_FEATURE_EFFECTS[key] ?? [];
    const ignoredFragments = IGNORED_FEATURE_RULES[key] ?? [];
    if (effects.length + ignoredFragments.length === 0) throw new Error(`Feature audit entry is unclassified: ${key}`);
    return [key, { effects, ignored: ignoredFragments }];
  })) as Record<AuditedFeatureKey, FeatureEffectAuditEntry>;
}
